"""Mutalia-e-Quran XII PDF75: p.72 — verses 5:70 (begun on p.71)–76 (5:77 begins at the foot; recorded on p.73). Run: python class12_quran_page075.py"""
from class12_quran_common import BOOK, Builder, rec, V


